package net.zartra.gui;
import org.bukkit.configuration.ConfigurationSection;import org.bukkit.configuration.file.YamlConfiguration;import java.io.*;import java.util.*;
final class VariableStorage {private final File file;VariableStorage(File f){file=f;}void load(VariableStore store){if(!file.exists())return;YamlConfiguration y=YamlConfiguration.loadConfiguration(file);ConfigurationSection g=y.getConfigurationSection("global");if(g!=null)for(String k:g.getKeys(false))try{store.setGlobal(k,g.getString(k));}catch(Exception ignored){}ConfigurationSection p=y.getConfigurationSection("player");if(p!=null)for(String id:p.getKeys(false))try{UUID u=UUID.fromString(id);ConfigurationSection v=p.getConfigurationSection(id);if(v!=null)for(String k:v.getKeys(false))store.setPlayer(u,k,v.getString(k));}catch(Exception ignored){}}void save(VariableStore store)throws IOException{YamlConfiguration y=new YamlConfiguration();for(Map.Entry<String,String> e:store.globals().entrySet())y.set("global."+e.getKey(),e.getValue());for(Map.Entry<UUID,Map<String,String>> p:store.players().entrySet())for(Map.Entry<String,String> e:p.getValue().entrySet())y.set("player."+p.getKey()+"."+e.getKey(),e.getValue());File dir=file.getParentFile();if(!dir.exists())dir.mkdirs();File tmp=new File(dir,file.getName()+".tmp");y.save(tmp);if(file.exists()&&!file.delete())throw new IOException("replace failed");if(!tmp.renameTo(file))throw new IOException("rename failed");}}